-- The only colorscheme in the rice. It is rendered from the same mono bundle
-- as Hyprland, foot and the shell, so it cannot drift from the session tone.

vim.cmd.hi('clear')
vim.g.colors_name = 'generated'
vim.o.background = '{{bundle.tone}}'

